retval
PLS_INTEGER;
BEGIN
dequeue_options.consumer_name := 'RED';
retval := DBMS_AQ.DEQUEUE_ARRAY(
queue_name
=> 'my_multi_q',
dequeue_options
=> dequeue_options,
array_size
=> 10,
message_properties_array => msg_prop_array,
payload_array
=> payload_array,
msgid_array
=> msgid_array);
DBMS_OUTPUT.PUT_LINE('Number of messages dequeued: ' || retval);
