●例外
説明
例外
パラメータのいずれかがNULLの場合です。
INVALID_ARGUMENT
cipher_type値の設定が正しくない場合です。
INVALID_NTH_ARGUMENT
input_dataの長さが8の倍数でない場合です。
INVALID_INPUT
キー値の長さが必要サイズより小さい場合です。
KEY_TOO_SHORT
●例
DECLARE
data RAW(256);
key RAW(16);
encrypted_data RAW(256);
decrypted_data RAW(256);
iv RAW(256);
BEGIN
data := '0102030405AE030D0102030405AE030D';
key := '0A123B8E002CD3FFA021B3E800C23DFF';
iv := '00000000000000000000000000000000';
encrypted_data := DBMS_CRYPTO.ENCRYPT(
src => data,
cipher_type => DBMS_CRYPTO.ENCRYPT_AES128 + DBMS_CRYPTO.CHAIN_CBC +
DBMS_CRYPTO.PAD_PKCS5,
key => key,
init_vector => iv);
encrypted_data := DBMS_CRYPTO.DECRYPT(
src => encrypted_data,
cipher_type => DBMS_CRYPTO.ENCRYPT_AES128 + DBMS_CRYPTO.CHAIN_CBC +
DBMS_CRYPTO.PAD_PKCS5,
key => key,
init_vector => iv);
END;

