になるため、注意が必要です。

ResultSet rs = stmt.executeQuery("SELECT name, image FROM backgrounds");
while (rs.next()) {
bytes[] images = rs.getBytes(2);
try {
FileOutputStream fos = new FileOutputStream(rs.getString(1));
fos.write(images);
}
catch (Exception e) {
e.printStackTrace();
}
finally {
if (fos != null)
fos.close();
}
}

