す。詳細については、「第8章 エラー処理」を参照してください。
以下は、エラー処理の実行例です。
DECLARE
no_bonus exception;
the_sales NUMBER := 12000;
BEGIN
IF the_sales < 20000 THEN
raise no_bonus;
END IF;
DBMS_OUTPUT.PUT_LINE('Your bonus is $' || the_sales * 0.1);
EXCEPTION
WHEN no_bonus THEN
DBMS_OUTPUT.PUT_LINE('Sorry, increase the sales');
END;

